#!/usr/bin/env python3
"""Build a local browser for rehearsing recurring compound pattern bundles."""

from __future__ import annotations

import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / "research/compound-pattern-bundles.json"
OUT = ROOT / "writeups/compound-pattern-bundles.html"


def build() -> str:
    report = json.loads(SOURCE.read_text())
    bundles = report["bundles"]
    cards = []
    for bundle in bundles:
        examples = "".join(
            f"<li><code>{html.escape(example['review_id'])}</code> / <code>{html.escape(example['video_id'])}</code> — "
            f"{html.escape(example['left_label'])} + {html.escape(example['right_label'])}; "
            f"<a href=\"../{html.escape(example['writeup'])}\">source</a><blockquote>First move: {html.escape(example.get('left_excerpt', ''))}<br>Second move: {html.escape(example.get('right_excerpt', ''))}</blockquote></li>"
            for example in bundle["examples"]
        )
        cards.append(
            f"<article class=\"card\" data-search=\"{html.escape((bundle['bundle_id']+' '+bundle['candidate_form']).lower())}\">"
            f"<h2>{html.escape(bundle['bundle_id'])}</h2>"
            f"<p><strong>Co-occurrence:</strong> {bundle['cooccurrence_review_count']} reviews / {bundle['cooccurrence_video_count']} videos</p>"
            f"<p class=form>{html.escape(bundle['candidate_form'])}</p>"
            f"<p><strong>Practice:</strong> {html.escape(bundle['practice_prompt'])}</p>"
            f"<p><strong>Self-check:</strong> {html.escape(bundle['self_check'])}</p>"
            f"<p class=boundary><strong>Boundary:</strong> {html.escape(bundle['non_fit_warning'])}</p>"
            f"<details><summary>Source examples</summary><ul>{examples}</ul></details></article>"
        )
    data = json.dumps(bundles, ensure_ascii=False, separators=(",", ":"))
    return f"""<!doctype html>
<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Compound speech-pattern practice</title>
<style>:root{{--bg:#f6f7fb;--fg:#172033;--muted:#5b6475;--card:#fff;--line:#d9deea;--accent:#2457d6;--warn:#fff3d6}}body{{margin:0;background:var(--bg);color:var(--fg);font:16px/1.55 system-ui,sans-serif}}main{{max-width:1100px;margin:auto;padding:28px 18px 70px}}.intro{{color:var(--muted);max-width:900px}}.builder,.card{{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:18px;margin:16px 0}}.fields{{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px}}label{{display:flex;flex-direction:column;gap:4px;font-weight:600}}input,textarea,select{{box-sizing:border-box;padding:10px;border:1px solid var(--line);border-radius:8px;font:inherit;background:var(--card);color:var(--fg)}}textarea{{width:100%;min-height:180px}}button{{padding:10px 14px;border:0;border-radius:8px;background:var(--accent);color:#fff;font:inherit;cursor:pointer;margin:6px 6px 6px 0}}.form{{color:var(--accent);font-weight:500}}.boundary{{background:var(--warn);padding:10px;border-radius:6px}}.count{{color:var(--muted)}}a{{color:var(--accent)}}code{{font-size:.9em}}@media(prefers-color-scheme:dark){{:root{{--bg:#101522;--fg:#f3f5fb;--muted:#acb5c8;--card:#171e2e;--line:#303a50;--warn:#3b301d}}}}</style></head><body><main>
<h1>Compound speech-pattern practice</h1><p class=\"intro\">These bundles pair recurring candidate moves found together in the full-context corpus. Co-occurrence is a discovery lead, not proof that the moves work better together or belong in this order.</p>
<section class=builder><h2>Rehearse one compound move</h2><div class=fields><label>Topic<input id=topic placeholder=\"What is the talk about?\"></label><label>Audience<input id=audience placeholder=\"Who is listening?\"></label><label>Bundle<select id=bundle-select><option value=\"\">Choose a bundle…</option>{''.join(f'<option value=\"{html.escape(b["bundle_id"])}\">{html.escape(b["bundle_id"])} ({b["cooccurrence_review_count"]} reviews)</option>' for b in bundles)}</select></label></div><p id=selected-form></p><label>Draft both moves<textarea id=draft placeholder=\"Choose a bundle, then write the first move and how the second follows.\"></textarea></label><p id=selected-check></p><p id=selected-boundary class=boundary></p><div class=fields><label>Listener restatement<textarea id=listener-restatement placeholder=\"What did the listener say they heard?\"></textarea></label><label>Still unclear<textarea id=still-unclear placeholder=\"What remained unclear or unanswered?\"></textarea></label><label>Non-fit or pressure point<textarea id=non-fit placeholder=\"What did not fit this person or context?\"></textarea></label><label>Next revision<textarea id=next-revision placeholder=\"What will you change next time?\"></textarea></label></div><button id=generate type=button>Generate scaffold</button><button id=save type=button>Save locally</button><button id=load type=button>Load saved</button><button id=download type=button>Download JSON</button><button id=download-md type=button>Download Markdown</button><span id=status role=status></span></section>
<label>Find a bundle<input id=search type=search placeholder=\"Try audience, story, qualification…\"></label><p class=count id=count></p><section id=cards>{''.join(cards)}</section>
<script>const bundles={data};const byId=Object.fromEntries(bundles.map(b=>[b.bundle_id,b]));const select=document.getElementById('bundle-select');const draft=document.getElementById('draft');function showSelected(){{const b=byId[select.value];document.getElementById('selected-form').textContent=b?'Candidate form: '+b.candidate_form:'';document.getElementById('selected-check').textContent=b?'Self-check: '+b.self_check:'';document.getElementById('selected-boundary').textContent=b?'Boundary: '+b.non_fit_warning:'';}}select.addEventListener('change',showSelected);document.getElementById('generate').addEventListener('click',()=>{{const b=byId[select.value];if(!b){{document.getElementById('status').textContent='Choose a bundle first.';return}}const topic=document.getElementById('topic').value||'[topic]';const audience=document.getElementById('audience').value||'[audience]';draft.value='# Compound presentation: '+topic+'\\n\\nAudience: '+audience+'\\n\\nMove 1: '+b.left_pattern+'\\nWrite the first move in your own words.\\n\\nBridge: Explain why the second move follows here.\\n\\nMove 2: '+b.right_pattern+'\\nWrite the second move, including its condition or limit.\\n\\nListener check: '+b.self_check+'\\nBoundary: '+b.non_fit_warning;}});document.getElementById('save').addEventListener('click',()=>{{localStorage.setItem('compound-pattern-draft',JSON.stringify({{topic:document.getElementById('topic').value,audience:document.getElementById('audience').value,bundle_id:select.value,draft:draft.value,reflections:Object.fromEntries(['listener-restatement','still-unclear','non-fit','next-revision'].map(id=>[id,document.getElementById(id).value])),saved_at:new Date().toISOString()}}));document.getElementById('status').textContent='Saved on this device.'}});document.getElementById('load').addEventListener('click',()=>{{const raw=localStorage.getItem('compound-pattern-draft');if(!raw){{document.getElementById('status').textContent='No saved draft on this device.';return}}const p=JSON.parse(raw);document.getElementById('topic').value=p.topic||'';document.getElementById('audience').value=p.audience||'';select.value=p.bundle_id||'';draft.value=p.draft||'';['listener-restatement','still-unclear','non-fit','next-revision'].forEach(id=>document.getElementById(id).value=(p.reflections||{{}})[id]||'');showSelected();document.getElementById('status').textContent='Loaded from this device.'}});document.getElementById('download').addEventListener('click',()=>{{const b=byId[select.value];const payload={{record_type:'local_compound_pattern_practice_record',schema_version:'1.0',topic:document.getElementById('topic').value,audience:document.getElementById('audience').value,bundle_id:select.value,source_review_ids:b?b.examples.map(x=>x.review_id):[],source_evidence_ids:b?b.examples.flatMap(x=>x.left_evidence_ids.concat(x.right_evidence_ids)):[],draft:draft.value,reflections:Object.fromEntries(['listener-restatement','still-unclear','non-fit','next-revision'].map(id=>[id,document.getElementById(id).value])),claim_boundary:'Local compound candidate practice record; not recurrence proof, learner-validation evidence, listener outcome evidence, causal evidence, or effectiveness evidence.',saved_at:new Date().toISOString()}};const blob=new Blob([JSON.stringify(payload,null,2)],{{type:'application/json'}});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='compound-pattern-practice-record.json';a.click();URL.revokeObjectURL(a.href)}});document.getElementById('download-md').addEventListener('click',()=>{{const b=byId[select.value];const reflection=['listener-restatement','still-unclear','non-fit','next-revision'].map(id=>'## '+id+'\\n'+(document.getElementById(id).value||'[not recorded]')).join('\\n\\n');const text='# Compound presentation practice\\n\\nTopic: '+(document.getElementById('topic').value||'[not recorded]')+'\\n\\nAudience: '+(document.getElementById('audience').value||'[not recorded]')+'\\n\\nBundle: '+(select.value||'[not selected]')+'\\n\\n'+(draft.value||'[draft not recorded]')+'\\n\\n'+reflection+'\\n\\n## Source evidence\\n'+(b?b.examples.flatMap(x=>x.left_evidence_ids.concat(x.right_evidence_ids)).join(', '):'[not selected]')+'\\n\\n## Boundary\\n'+(b?b.non_fit_warning:'Local compound candidate practice record; not effectiveness evidence.');const blob=new Blob([text],{{type:'text/markdown'}});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='compound-pattern-practice.md';a.click();URL.revokeObjectURL(a.href)}});const search=document.getElementById('search');function filter(){{const q=search.value.toLowerCase();let n=0;document.querySelectorAll('.card').forEach(card=>{{const hit=!q||card.dataset.search.includes(q);card.hidden=!hit;if(hit)n++}});document.getElementById('count').textContent=n+' bundles shown';}}search.addEventListener('input',filter);filter();</script></main></body></html>"""


if __name__ == "__main__":
    OUT.write_text(build())
    print(f"compound pattern browser: {len(json.loads(SOURCE.read_text())['bundles'])} bundles")
